(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.headline":"<span class=\"hl-muted\">السلسلة الصوتية لكل عصر.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">إضافة واحدة.</span>","hero.cycle":"إضافة واحدة.|على صوتك.|في كل DAW.","hero.sub":"ابحث عن فنان، واختر عصرًا، واضغط تشغيل. يحمّل Takelight السلسلة الصوتية كاملة — ضبط النغمة، والمعادل، والضغط، وإزالة الصفير، والتأخير، والصدى، وناقل الصوت — مبنية من وحداته الخاصة. يعمل دون اتصال وخالٍ من الذكاء الاصطناعي بنسبة 100%.","price.note":"لا شيء معروض للبيع بعد. بدءًا من الإصدار 1.0، سيُباع Freally Takelight بترخيص يُدفع مرة واحدة، تسبقه تجربة مجانية للإضافة كاملة.","hero.chipStandalone":"مستقل","what.title":"ما هو","what.p1":"الصوت الخام لا يبدو كالتسجيل، والفرق هو سلسلة: الضبط النغمي، ومعادلات EQ، وضواغط، ومزيل صفير، وتأخيرات وصدى على الإرسالات، وناقل صوتي، بالترتيب الصحيح وبالإعدادات الصحيحة.","what.p2":"يحتفظ Takelight بسلسلة كاملة لكل فنان ولكل عصر داخل إضافة واحدة، مبنية من وحداته الخاصة، فلا تحتاج أبدًا إلى إضافة أخرى لتسمعها.","what.p3":"حمّل سلسلة فتدخل بانتقال سلس دون أي نقرة. شكّلها بأربعة ماكرو، أو افتح الرفّ وأدر أي مقبض.","features.title":"ما الذي يحتويه","featuresPage.cards.chains.title":"سلاسل حسب الفنان والعصر","featuresPage.cards.chains.body":"اكتب اسم فنان، واختر عصرًا ودورًا — «رئيسي» أو «إضافات» — فتُحمَّل السلسلة كاملة بالترتيب: الإدراجات، ومسارات إرجاع المؤثرات، وناقل الصوت.","featuresPage.cards.swap.title":"تبديل دون نقرات","featuresPage.cards.swap.body":"بدّل السلسلة والمقطع يعمل. تُجهَّز السلسلة الجديدة بعيدًا عن الصوت وتدخل بانتقال مدته 30 ميلي ثانية، فلا تُسمع أي فرقعة.","featuresPage.cards.joint.title":"Joint","featuresPage.cards.joint.body":"رفّ واحد يضم السلسلة كلها: تصحيح طبقة الصوت، وثلاثة أنواع من EQ، وخمسة أنواع من الضواغط، ومزيل صفير، وبوابة، وتشبّع، ومُثير، ولو-فاي، ومحدِّد، ومضاعِف، وتأخيرات، وصدى، وأربع عودات، وناقل صوتي.","featuresPage.cards.modes.title":"بسيط ومتقدم","featuresPage.cards.modes.body":"يعرض الوضع البسيط أربعة ماكرو — «ضبط النغمة» و«النبرة» و«المساحة» و«المقدار». ويعرض الوضع المتقدم كل وحدة كجهاز مُصيَّر، وترسم كل بطاقة ما تفعله وحدتها — منحنى EQ فوق صوتك الغنائي، ومنحنى الضاغط وما يقتطعه — ويمكن أتمتة كل مقبض.","featuresPage.cards.daw.title":"في كل DAW","featuresPage.cards.daw.body":"CLAP وVST3 على Windows وmacOS وLinux، وAU على macOS، وتطبيق مستقل. يُحفظ مع مشروعك، ويُبلغ عن زمن التأخير كي يحاذي DAW كل شيء، ويعمل بأمان في نسخ كثيرة في آن واحد.","featuresPage.cards.offline.title":"بلا اتصال، خاص، بلا ذكاء اصطناعي","featuresPage.cards.offline.body":"لا حساب ولا قياس عن بُعد ولا نموذج. لا تتصل الإضافة ولا التطبيق بالإنترنت أبدًا؛ ويعمل التحقق من التحديثات وتفعيل الترخيص في برنامج مساعد منفصل، فقط عندما تطلب.","ladder.title":"الطريق إلى 1.0","ladder.intro":"سطر واحد لكل إصدار. هذا هو السلّم نفسه الذي تتبعه الخطة الخاصة — إن تحرّك أحدهما تحرّك الآخر، وتقارنهما بوابة بناء.","ladder.rung.v0.1.0":"الأساس: يُحمَّل المكوّن الإضافي بصيغ CLAP وVST3 وAU وكتطبيق مستقل، ويمرّر صوتك دون أن يمسّه، ويطلب منك قبول ترخيصه، وتعمل كل بوابات الجودة.","ladder.rung.v0.2.0":"Joint: رفّ واحد لسلسلة صوتية كاملة، وأولى وحدات EQ والديناميكية واللون على أجهزة مُصيَّرة، ومصباح التسجيل.","ladder.rung.v0.3.0":"المساحة: التأخيرات والصدى والمضاعفة والعرض والعودات الأربع للمؤثرات، على إيقاع مشروعك.","ladder.rung.v0.4.0":"ضبط النغمة: تصحيح طبقة الصوت بمعالجة الإشارة الكلاسيكية، والمقام المحدد من صوتك، ووضع بزمن تأخير منخفض للتسجيل.","ladder.rung.v0.5.0":"الضوء الأول: ابحث عن فنان وعصر، فتُحمَّل السلسلة كاملة بنقرة واحدة. أول إصدار مكتمل.","ladder.rung.v0.5.5":"Input Check، وسلاسل «الإضافات»، وإعداداتك المسبقة الخاصة، والتراجع.","ladder.rung.v0.5.6":"بطاقات مرئية: تعرض كل وحدة ما تفعله — منحنى EQ فوق طيف حيّ لصوتك الغنائي، ومنحنى الضاغط مع ما يقتطعه — لا المقابض وحدها.","ladder.rung.v0.6.0":"الموجة الأولى من سلاسل الفنانين، وسلسلة لكل نوع موسيقي، وصفحة القائمة.","ladder.rung.v0.7.0":"في كل DAW: يُحفظ مع مشروعك، ويمكن أتمتته، ويُبلغ عن زمن تأخيره، ويعمل بأمان في نسخ كثيرة في آن واحد.","ladder.rung.v0.8.0":"التطبيق المستقل بكامل قوته، وTakelight على macOS وLinux.","ladder.rung.v0.9.0":"الموجة الثانية من سلاسل الفنانين، وجولة للواقعية والأداء.","ladder.rung.v0.9.5":"Reference Match: حمّل مرجعًا، فيقرأ Takelight التأخيرات والصدى المتردد والنبرة وسائر ما في صوته الغنائي، ويقترحها على وحداته الخاصة.","ladder.rung.v1.0.0-beta":"مُحصَّن: مثبّتات لثلاثة أنظمة، والتحقق من التحديثات، والتجربة والترخيص، والدليل الكامل. ولا تنزيلات على هذا الموقع بعد.","ladder.rung.v1.0.0-rc":"الإصدار المرشّح: مراجعة كل ملف واختبار كل مضيف يدويًا.","ladder.rung.v1.0.0":"الإصدار: التجربة المجانية، والترخيص الذي يُدفع مرة واحدة، وأول تنزيلات يقدّمها هذا الموقع على الإطلاق.","ladder.rung.v1.1.0":"Vocal Match: نبرة صوتك مضبوطة مقابل مرجع تملكه.","ladder.rung.v1.2.0":"طبقات مضاعفة وهارموني، مكدّسة لك.","ladder.rung.v1.3.0":"موجة ثالثة من سلاسل الفنانين، وسلاسل يرسلها المنتجون.","ladder.rung.v1.4.0":"جسور إلى Freally MIDI Master وFreally Unloop.","ladder.rung.v1.5.0":"Pro Tools كإضافة (AAX)، إن سمحت شروط Avid بذلك.","ladder.note":"الإصدار المكتمل مبنيّ ومُوسوم. إنه ليس تنزيلًا: لا يوجد أي منها، ولن يوجد حتى الإصدار 1.0.0.","honest.title":"الأشياء التي تضعها معظم المواقع في الأسفل","honest.voice.title":"السلسلة ليست صوتًا","honest.voice.body":"السلسلة تعيد إنتاج المعالجة: الضبط النغمي وEQ والضغط والتأخير والصدى. صوتك وميكروفونك وغرفتك وأداؤك تبقى لك، ولا يجعل أي إعداد مسبق أحدًا يبدو مثل شخص آخر.","honest.start.title":"السلسلة نقطة بداية","honest.start.body":"السلسلة هي حيث يبدأ صوتك، لا وعد بصوت معيّن. أدر الماكرو، وافتح الرفّ، واجعلها لك؛ لا شيء تغيّره يُقفل أبدًا.","honest.downloads.title":"لا توجد تنزيلات قبل 1.0.0","honest.downloads.body":"لا نسخة تجريبية على هذه الصفحة، ولا بناء معاينة، ولا وصول مبكر. يأتي الإصدار 1.0 مع تجربة مجانية للإضافة كاملة وترخيص يُدفع مرة واحدة.","honest.network.title":"لا تتصل بالإنترنت أبدًا","honest.network.body":"لا تحتوي الإضافة ولا التطبيق المستقل على أي شيفرة شبكات، وتفشل بوابة البناء إن أُضيف شيء منها. وسيعيش التحقق من التحديثات وتفعيل الترخيص في برنامج مساعد منفصل لا يعمل إلا عندما تطلب.","site.tagline":"السلسلة الصوتية لكل عصر. إضافة واحدة.","footer.licence":"برنامج مملوك — جميع الحقوق محفوظة. © Mike Weaver. ليس مفتوح المصدر. للتواصل: freallyproducts@gmail.com.","footer.yours":"الصوت والإعدادات المسبقة والمشاريع التي تصنعها بـ Freally Takelight ملكك.","footer.disclaimer":"تدل أسماء الفنانين على أسلوب فقط. لا يرتبط Freally Takelight بأي فنان أو منتج أو مهندس أو شركة تسجيلات أو مطبوعة أو صانع إضافات، ولا يحظى بتأييدهم أو موافقتهم. السلسلة تطبّق معالجة، لا صوتًا.","featuresPage.lead":"إضافة صوتية واحدة فيها سلسلة صوتية كاملة لكل فنان ولكل عصر — ضبط النغمة، والمعادل، والضغط، وإزالة الصفير، والتأخير، والصدى، وناقل الصوت — مبنية من وحداتها الخاصة.","featuresPage.version":"تصف هذه الصفحة الإصدار 1.0 من Freally Takelight: كل ما فيها موجود في 1.0، ولا شيء مما هو مخطط لما بعد 1.0 مذكور فيها.","featuresPage.numbers.plugin":"إضافة للسلسلة كلها، دون إضافة أخرى تشتريها","featuresPage.numbers.macros":"ماكرو: «ضبط النغمة» و«النبرة» و«المساحة» و«المقدار»","featuresPage.numbers.returns":"عودات مؤثرات، إضافة إلى ناقل صوتي","featuresPage.numbers.plugins":"صيغ مكوّنات إضافية، إضافةً إلى تطبيق مستقل","featuresPage.numbers.systems":"أنظمة تشغيل: Windows وmacOS وLinux","featuresPage.numbers.languages":"لغة","featuresPage.numbers.ai":"نماذج ذكاء اصطناعي","featuresPage.numbers.borrowed":"استجابات نبضية أو عينات أو إعدادات مسبقة منسوخة","featuresPage.free.title":"لا شيء للشراء بعد","featuresPage.free.body":"قبل الإصدار 1.0 لا يوجد ما يُباع ولا ما يُنزَّل. بعد ذلك تأتي تجربة مجانية للإضافة كاملة وسعر واحد يُدفع مرة واحدة: بلا اشتراك وبلا حساب. والصوت الذي تصنعه به ملكك.","featuresPage.cards.title":"ما يفعله الإصدار 1.0","featuresPage.cards.tune.title":"ضبط النغمة وAuto Key","featuresPage.cards.tune.body":"تصحيح طبقة الصوت بمعالجة الإشارة الكلاسيكية، مع تحديد المقام من صوتك أو من سلسلة جانبية، ووضع بزمن تأخير منخفض للتسجيل عبره.","featuresPage.cards.inputCheck.title":"Input Check وA/B","featuresPage.cards.inputCheck.body":"يستمع Input Check إلى عشر ثوانٍ من مقطعك ويضبط مقبض الدخل، والبوابة والتمرير العالي ومزيل الصفير الموجودة في سلسلتك. وتقارن A/B السلسلة بملف مرجعي تحمّله، بعلوّ صوت متساوٍ، أو بنسخة ثانية منها؛ ولا يُحفظ المرجع أبدًا.","featuresPage.cards.lightDark.title":"الوضعان الفاتح والداكن","featuresPage.cards.lightDark.body":"وضع داكن ووضع فاتح، كلاهما بأخضر Freally، مع كل مقبض ومنزلق ومفتاح مُصيَّر في Blender لكل وضع، ومصباح التسجيل الذي يضيء حين تعمل السلسلة.","featuresPage.compare.title":"جنبًا إلى جنب مع الأدوات التجارية","featuresPage.compare.intro":"Freally Takelight 1.0 بجانب إضافات الصوت التي يلجأ إليها المنتجون حين يريدون صوتًا له اسم. كل خانة لمنتج آخر مأخوذة من صفحات صانعه أو من تغطية منشورة، تحققنا منها في أكتوبر 2026؛ والخانة التي لا تحسمها تقول «لم يُتحقق منه».","featuresPage.compare.feature":"الميزة","featuresPage.compare.row.price":"السعر (USD، أكتوبر 2026)","featuresPage.compare.ourPrice":"سعر واحد، مرة واحدة، بعد تجربة مجانية","featuresPage.compare.note.muzePrice":"مدى الحياة، أو $24 كل 4 أسابيع","featuresPage.compare.legend.unknown":"لم يُتحقَّق منه","featuresPage.compare.row.artists":"سلاسل بأسماء فنانين","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.note.artistEra":"حسب الفنان والعصر والدور","featuresPage.compare.note.muzePresets":"52 إعدادًا مسبقًا لفنانين","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.note.engineerChain":"سلسلة مهندس واحد","featuresPage.compare.note.producerChain":"سلسلة منتج واحد","featuresPage.compare.row.modes":"وضعان بسيط ومتقدم","featuresPage.compare.row.key":"يحدد المقام من صوتك","featuresPage.compare.row.formats":"CLAP وVST3 وAU","featuresPage.compare.legend.partly":"جزئيًا","featuresPage.compare.row.systems":"Windows وmacOS وLinux","featuresPage.compare.row.noAi":"بلا ذكاء اصطناعي ولا تعلّم آلي","featuresPage.compare.summaryTitle":"باختصار","featuresPage.compare.summary":"وحده Takelight يقدّم سلاسل حسب الفنان والعصر والدور، وصيغ الإضافات الثلاث كلها، وLinux إلى جانب Windows وmacOS، ولا ذكاء اصطناعي على الإطلاق.","featuresPage.compare.theyWinTitle":"أين يتفوّقون","featuresPage.compare.theyWin":"لدى Muze اليوم 52 إعدادًا مسبقًا لفنانين ويعمل في Pro Tools؛ أما أولى سلاسل الفنانين في Takelight فوصلت مع الإصدار 0.5.0، وليس إضافة لـ Pro Tools في الإصدار 1.0. وقد صُنع CLA Vocals وThe Spirit مع المهندس والمنتج اللذين يحملان اسميهما.","featuresPage.compare.asOf":"عمود Takelight هو الإصدار 1.0، الذي لم يصدر بعد. والمنتجات الأخرى تتغير أيضًا؛ هذا الجدول بحسب أكتوبر 2026. أسماء المنتجات ملك لأصحابها وتُستخدم هنا للمقارنة فقط.","featuresPage.why.title":"لماذا بُني بهذه الطريقة","featuresPage.why.built.title":"مبنيّ، لا مستعار","featuresPage.why.built.body":"كل وحدة هي معالجة إشارة كلاسيكية خاصة بـ Takelight. لا استجابات نبضية ولا عينات ولا شيفرة مستعارة ولا إعدادات منسوخة من الإعدادات المسبقة لمنتج آخر.","featuresPage.why.names.title":"أسماء صادقة","featuresPage.why.names.body":"تحمل السلسلة اسم الفنان والعصر، ولا شيء أكثر. لا صورة، ولا غلاف، ولا وعد بأن يبدو أحد مثل شخص آخر.","featuresPage.why.reference.title":"مرجعك بالمستوى نفسه","featuresPage.why.reference.body":"تضع A/B ملف المرجع الذي تحمّله إلى جانب صوتك بارتفاع الصوت نفسه، حتى لا تخدع النسخة الأعلى أذنك أبدًا. يبقى المرجع في الذاكرة ولا يُحفظ أبدًا.","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"لا قياس عن بُعد ولا سحابة. صوتك لا يغادر جهازك أبدًا، وتفشل بوابة البناء إن أُضيفت شيفرة شبكات يومًا إلى الإضافة أو التطبيق.","featuresPage.why.roster.title":"قائمة واحدة للعائلة","featuresPage.why.roster.body":"يتشارك الفنانون والأنواع الموسيقية أسماءهم مع Freally MIDI Master وFreally Unloop، فتمرّ قائمة واحدة عبر سلسلة Freally كلها.","featuresPage.coming.title":"ما الذي لم يأتِ بعد","featuresPage.coming.intro":"نقولها بوضوح، لأن قائمة ميزات تخفي ثغراتها لا تستحق القراءة. تصف هذه الصفحة الإصدار 1.0، ويُبنى Takelight درجة بعد درجة: لم يُبنَ كل ما فيها بعد. وكل درجة على الطريق إلى 1.0 معلَّمة بحالتها.","featuresPage.limits.title":"ما لا يفعله الإصدار 1.0","featuresPage.limits.voice":"لا يغيّر من يغنّي، ولا يقلّد أي صوت أبدًا.","featuresPage.limits.roster":"لا يضم كل الفنانين. تكبر القائمة مع كل إصدار.","featuresPage.limits.match":"لا يطابق صوتك مع مرجع تلقائيًا؛ ومن المخطط إطلاق Vocal Match بعد 1.0.","featuresPage.limits.aax":"ليس إضافة لـ Pro Tools (AAX) في الإصدار 1.0.","featuresPage.coming.downloads":"لا توجد تنزيلات قبل الإصدار 1.0، ولا شيء منها على هذه الصفحة.","docs.intro":"يكبر هذا الدليل مع كل إصدار. يغطي الآن العثور على سلسلة، وإعداداتك المسبقة، والوضع البسيط ومقابضه الأربعة، وA/B، والرفّ وما تعرضه كل بطاقة، والتراجع، وقنوات إرجاع المؤثرات الأربع فيه، وضبط النغمة، وInput Check، ووحداته الخمس والعشرين.","docs.start.title":"البدء","docs.browser.title":"العثور على سلسلة","docs.presets.title":"إعداداتك المسبقة","docs.simple.title":"الوضع البسيط والمقابض الأربعة","docs.ab.title":"A/B","docs.rack.title":"الرفّ","docs.cards.title":"ما تعرضه كل بطاقة","docs.undo.title":"التراجع والإعادة","docs.returns.title":"قنوات الإرجاع والرمي","docs.tune.title":"ضبط النغمة وAuto Key","docs.inputCheck.title":"Input Check","docs.automation.title":"الأتمتة","docs.lamp.title":"مصباح التسجيل والمقاييس","docs.modules.title":"الوحدات","docs.project.title":"محفوظ مع مشروعك","docs.agreement.title":"اتفاقية الترخيص","docs.settings.title":"الإعدادات","docs.language.title":"اللغات","docs.disclaimer.title":"إخلاء المسؤولية","docs.privacy.title":"الخصوصية والشبكة","docs.report.title":"عندما يحدث خطأ ما","docs.start.p1":"يعمل Takelight داخل DAW الخاص بك كإضافة CLAP أو VST3 أو AU، أو وحده كتطبيق مستقل. ضعه على مسار صوتي. يُفتح في الوضع البسيط: ابحث عن فنان أو نوع موسيقي، واختر عصرًا ودورًا، فتُحمَّل السلسلة كلها. وإلى أن تحمّل سلسلة أو تضيف وحدة، يمرّ صوتك دون تغيير.","docs.start.p2":"لا تنزيلات قبل الإصدار 1.0.0، والشيفرة خاصة.","docs.browser.p1":"اكتب في مربع البحث في الأعلى — اسم فنان أو لقبًا أو نوعًا موسيقيًا — أو اضغط Ctrl+K (أو Cmd+K على Mac) من أي مكان. تظهر السلاسل وأنت تكتب: كل فنان بعصوره، وكل عصر بسنواته وأدواره، مثل «رئيسي» أو «إضافات» أو «مؤثرات». اختر واحدة فتُحمَّل السلسلة كلها بالترتيب، دون نقرات، والمقطع يعمل. تتنقّل مفاتيح الأسهم في القائمة، ويحمّل Enter، ويغلقها Escape.","docs.browser.p2":"حين يكون البحث فارغًا، يعرض السلاسل التي حمّلتها آخر مرة. ولفنان ليست له سلسلة بعد، يعرض سلاسل من نوعه الموسيقي؛ وإن لم يعرف اسمًا، قال ذلك واقترح نوعًا موسيقيًا.","docs.browser.p3":"في الإصدار 0.5.6 يأتي Drake في ثلاثة عصور — So Far Gone (2009) وTake Care (2011) والعصر الحديث (2016–2026) — مع سلسلة مؤثرات من عصر Take Care، وثماني عشرة سلسلة للأنواع الموسيقية: سلسلة رئيسية وسلسلة إضافات لكل من التراب (عقد 2000 وعقد 2010)، ودريل شيكاغو، والإيمو راب، والـ R&B الكلاسيكي، والبوب الحديث، والروك، والكانتري بوب، والريغيتون. تحمل كل سلسلة اسم فنانها أو نوعها الموسيقي وعصرها، ولا شيء أكثر.","docs.presets.p1":"يحفظ «حفظ إعداد مسبق…» في الأعلى السلسلةَ كما شكّلتها — كل وحدة ومقبض وإرسال ومنزلق، ومقابض الوضع البسيط الأربعة — باسم تختاره. وكل إعداد مسبق ملف في المستندات › Freally Takelight › Presets، فيمكنك نسخه احتياطيًا أو إرساله إلى أحد.","docs.presets.p2":"يعرضها «إعداداتي المسبقة…» في قائمة، كلًّا منها مع السلسلة التي صُنع منها، لتحميله أو إعادة تسميته أو تصديره أو حذفه. ويجلب «استيراد…» إعدادًا مسبقًا أرسله إليك أحد، ويرقّم اسمه إن كان لديك واحد بالاسم نفسه. ويُرفض الملف الذي ليس إعدادًا مسبقًا من Takelight، أو يزيد حجمه على 256 KB، أو حُفظ بإصدار أحدث، وتقول القائمة السبب.","docs.presets.p3":"وتظهر إعداداتك المسبقة في البحث أيضًا، تحت «إعداداتي المسبقة». وحين تُحدَّث السلسلة التي صُنع منها إعداد مسبق في إصدار لاحق، يُحمَّل الإعداد المسبق على السلسلة المحدَّثة ويحتفظ بكل تغيير أجريته، ويقول ذلك.","docs.simple.p1":"يعرض الوضع البسيط مصباح التسجيل واسم السلسلة وأربعة مقابض كبيرة ومقياسي الدخل والخرج؛ ويعرض الوضع المتقدم، من المفتاح في الأعلى، الرفّ كله. يتذكر مشروعك العرض الذي تركته فيه، وتختار في الإعدادات العرض الذي يُفتح فيه مشروع جديد.","docs.simple.p2":"يحدد «ضبط النغمة» سرعة ضبط الصوت الغنائي ومدى طبيعيته. وتجعل «النبرة» السلسلة أكثر قتامة أو أكثر سطوعًا، حول 1 kHz، ويتبعها مزيل الصفير. وترفع «المساحة» كل إرسالات المؤثرات أو تخفضها معًا، بما يصل إلى 12 dB. ويضبط «المقدار» السلسلة كلها مقابل صوتك الجاف، من الصوت الجاف وحده عند 0 % إلى السلسلة كاملة عند 100 %.","docs.simple.p3":"حين يكون «ضبط النغمة» و«النبرة» و«المساحة» في المنتصف و«المقدار» عند 100 %، تعمل السلسلة كما صُمّمت، وهكذا تُحمَّل كل سلسلة. وكل مقبض معلمة مضيف، فيستطيع DAW الخاص بك أتمتته، وتعيده النقرة المزدوجة إلى موضعه.","docs.ab.p1":"يفتح «تحميل مرجع…» مربع حوار الملفات في نظامك، أو أفلت ملفًا على النافذة. يقرأ ملفات WAV وAIFF وFLAC وMP3، حتى 20 دقيقة، ويعرض الشريط اسم الملف وطوله وجهارته. يشغّل B المرجع من حيث يقف DAW الخاص بك (من البداية في التطبيق المستقل)، وA سلسلتك، وكل تبديل انتقال سلس مدته 20 ميلي ثانية.","docs.ab.p2":"يشغّل «مطابقة الجهارة» المرجع بجهارة صوتك الغنائي، فتحكم على النبرة لا على المستوى. ويبقى المرجع في الذاكرة فقط: لا يُحفظ أبدًا مع مشروعك ولا في إعداد مسبق ولا في أي مكان آخر، ويُرفض أي ملف على محرك أقراص شبكي.","docs.ab.p3":"يحتفظ «قارن السلاسل» بنسختين من سلسلتك. A هي التي تحرّرها؛ اضغط B فتبدأ نسخةً منها، فلا يتغير شيء؛ حرّرها، فتحتفظ كل من A وB بتعديلاتها. وتُحفظ النسختان مع مشروعك.","docs.rack.p1":"يضم الرفّ السلسلة كلها بترتيب الإشارة، في أربعة صفوف: المرحلة الأولى (الخانتان F1 وF2)، والإدراجات (من I1 إلى I12)، وقنوات إرجاع المؤثرات الأربع (من A إلى D، الخانات من R1 إلى R12)، والناقل (من B1 إلى B4).","docs.rack.p2":"اختر وحدة من قائمة خانة فارغة لإضافتها. تعرض بطاقتها كل عناصر التحكم فيها: مقابض للقيم، ومفاتيح، وقوائم للخيارات. ويضم رأسها طابعها (إن كان لها أكثر من طابع)، و«تجاوز» (B) و«منفرد» (S) وعلامة × التي تُخرجها.","docs.rack.p3":"كل تغيير يتم دون نقرات. الوحدة التي تضيفها أو تُخرجها تتلاشى دخولًا أو خروجًا، والطابع الجديد يدخل بانتقال سلس، وكل مقبض ينزلق بنعومة، فيمكنك العمل والمقطع يعمل. والوحدة المتجاوَزة تحتفظ بزمن تأخيرها، فيبقى DAW الخاص بك متزامنًا.","docs.rack.p4":"كل عنصر تحكم يعمل من لوحة المفاتيح. ينتقل Tab بينها؛ وتدير مفاتيح الأسهم المقبض، ويديره Shift بخطوات أكبر؛ ويأخذه Home وEnd إلى أحد الطرفين؛ وتعيده النقرة المزدوجة إلى قيمته الافتراضية.","docs.rack.p5":"يتّسع الرفّ لعدد من المقابض يساوي ما يستطيع Takelight تحريكه دفعة واحدة — وامتلاء كل خانة بأكبر الوحدات سيتجاوز ذلك — لذا تُرفض أي وحدة بعد هذا الحد ويقول الرفّ إنه ممتلئ.","docs.cards.p1":"إلى جانب مقابضها، ترسم بطاقة كل وحدة ما تفعله، محسوبًا بالرياضيات نفسها التي تصنع الصوت. ترسم وحدات EQ — البارامتري وطاولة المزج والبرنامج — منحناها فوق صوتك الغنائي في أثناء تشغيله: طيفه قبل EQ باهتًا، وبعده ساطعًا، مع إبقاء القمم لحظةً. لكل نطاق نقطة على المنحنى: اسحبها لتحريك تردد النطاق وكسبه معًا، وأدر عجلة الفأرة فوقها لعرض النطاق، وانقر عليها نقرًا مزدوجًا لإعادة النطاق إلى وضعه، أو استخدم مفاتيح الأسهم. والسحب الكامل خطوة واحدة في التراجع. ويرسم مزيل الصفير النطاق الذي يستمع إليه والخفض الذي يُحدثه، ويرسم ضبط الكسب مرشّح التمرير العالي الخاص به.","docs.cards.p2":"ترسم الضواغط ومُتابع المستوى والمحدِّد منحناها — مستوى الدخل مقابل مستوى الخرج — مع نقطة حيث يقع صوتك الغنائي عليه الآن، وتحته خفض الكسب في آخر أربع ثوانٍ. تضع النوتة الثابتة النقطة على المنحنى؛ وقد يرفعها هجوم حادّ فوقه لحظةً، قبل أن يلتقطه الضاغط. اسحب العتبة على طول المنحنى، أو استخدم مفاتيح الأسهم: فهي تدير المقبض الذي يضبطها. وتعرض بطاقة البوابة المستوى الذي تسمعه مقابل عتبتها، مظلَّلًا حيث تكون مغلقة.","docs.cards.p3":"يرسم التأخير تكراراته على خط زمني مقابل نبض مشروعك ومازورته، كلٌّ منها بالشدة التي تتركها له التغذية الراجعة والمرشّحات؛ وفي بينغ بونغ تقع التكرارات اليسرى فوق الخط واليمنى تحته. ويرسم الصدى المتردد تلاشيه — التأخير المسبق والانعكاسات المبكرة والذيل — وترسم البوابة المعكوسة تصاعدها. ويعرض المضاعِف والكورس والعرض المجال الستيريو من الأعلى، ويعرض التشبّع والمُثير ولو-فاي منحناها والتوافقيات التي يضيفها إلى صوتك الغنائي كما هو الآن.","docs.cards.p4":"لا ترسم إلا البطاقات الظاهرة على الشاشة، وتعرض حتى ثماني بطاقات EQ طيف صوتك الغنائي في آن واحد. أما ضبط النغمة فله رسم الطبقة بدلًا من ذلك، ولمُزيح الطبقة مقابضه وحدها.","docs.undo.p1":"يتراجع السهمان في الأعلى عن كل تغيير في الصوت ويعيدانه، حتى 100 خطوة: مقبض (السحب الكامل خطوة واحدة)، ووحدة تُضاف أو تُزال، وطابعها، و«تجاوز» و«منفرد»، والإرسالات والمنزلقات، ومقابض الوضع البسيط الأربعة، ومقبض الدخل، وسلسلة أو إعداد مسبق يُحمَّل، و«تطبيق» في Input Check. يتراجع Ctrl+Z، ويعيد Ctrl+Shift+Z أو Ctrl+Y (⌘Z و⌘⇧Z على Mac)، ما دامت نافذة Takelight في موضع التركيز، فيحتفظ DAW الخاص بك باختصاراته.","docs.undo.p2":"لا يُتراجع أبدًا عن العرض والسمة واللغة ومرجع A/B، ولا عن أتمتة DAW الخاص بك. ويبدأ كل مشروع بسجلّ جديد حين يُفتح، وكذلك كل جانب من جانبي المقارنة حين تنتقل إليه.","docs.returns.p1":"تُغذّى كل قناة من قنوات الإرجاع الأربع، من A إلى D، من نهاية صف الإدراجات عبر مقبض «الإرسال» الخاص بها، من «إيقاف» حتى +6 dB. يمرّ الصوت الغنائي عبر خانات الإرجاع الثلاث — تأخير وصدى متردد مثلًا — ويحدد منزلق مستوى الإرجاع مقدار ما ينضم منه إلى الصوت الجاف في طريقه إلى الناقل.","docs.returns.p2":"اضغط مع الاستمرار على مفتاح «رمي» في قناة إرجاع فيُرمى الصوت الغنائي إليها: يرتفع إرسالها إلى 0 dB، ثم يعود حين تُفلت المفتاح، خلال 5 ميلي ثانية في الاتجاهين. و«رمي» من A إلى D معلمات مضيف أيضًا، فيستطيع DAW الخاص بك تسجيل الرمية وإعادة تشغيلها — ذيل تأخير على كلمة واحدة.","docs.returns.p3":"التأخير المضبوط على قيمة نوتة يواكب سرعة إيقاع مشروعك، ويتبعها حين تتغير في أثناء الأغنية.","docs.tune.p1":"تشدّ وحدة ضبط النغمة كل نغمة مغنّاة إلى أقرب نغمة في سلّمها. تحدد «سرعة التصحيح» مدى السرعة: عند 0 ms يقفز الصوت من نغمة إلى أخرى، وهو الصوت الحاد المتدرّج؛ وبسرعة أبطأ ينزلق إليها، وعند بضع مئات من الميلي ثانية يصعب سماع الضبط. يجعل «الطابع البشري» النغمات الطويلة تستقر ببطء أكبر، وتحافظ «المرونة» على الانزلاقات والاهتزاز التي تبتعد أكثر عن النغمة. تبقى فورمانتات الصوت في مكانها، فيحافظ على طابعه، وتمرّ الأنفاس والحروف الساكنة دون أن تُمسّ.","docs.tune.p2":"تبدأ قائمة «السلّم» على Auto Key: تستمع وحدة ضبط النغمة إلى صوتك الغنائي وتستقر على سلّمه خلال نحو أربع ثوانٍ من الغناء، وتضبط إلى أقرب نصف نغمة حتى ذلك الحين، بينما يضيء مصباح التسجيل بالكهرماني. تعرض البطاقة السلّم الذي تسمعه، و«تثبيت» يُبقيه. أو اختر «كروماتي» أو أيًّا من السلالم الأربعة والعشرين بنفسك. وإن لم يُسمع أي سلّم بعد 20 ثانية من الغناء، تطلب منك البطاقة أن تختار واحدًا.","docs.tune.p3":"يعرض مخطط الطبقة آخر أربع ثوانٍ: الطبقة التي غنّيتها بخط رفيع، والطبقة التي ترسلها وحدة ضبط النغمة بخط أخضر، فوق خط للنغمة التي تشدّ إليها.","docs.tune.p4":"لتسمع وحدة ضبط النغمة النغمة قبل أن تضبطها، تنتظر 21 ميلي ثانية، ويُبلغ Takelight الـ DAW الخاص بك بذلك، فيبقى الصوت الغنائي متزامنًا مع الإيقاع. أثناء التسجيل سيكون هذا الانتظار في سماعتيك، لذا فإن معلمة المضيف Tracking، على Auto، تُنزل ضبط النغمة إلى 4 ميلي ثانية كلما سجّل الـ DAW، وتقول البطاقة ذلك. اضبط Tracking على On أو Off لتختار بنفسك.","docs.tune.p5":"يضم الرفّ وحدة ضبط نغمة واحدة، لأن وحدة واحدة تضبط الصوت الغنائي كله.","docs.tune.p6":"ويستطيع Auto Key أن يجد السلّم من الإيقاع بدلًا من ذلك. أرسل الإيقاع إلى مدخل السلسلة الجانبية في Takelight داخل DAW الخاص بك، واضبط «يستمع إلى» في بطاقة ضبط النغمة على «السلسلة الجانبية»: فيتبع ضبط النغمة تآلفات الإيقاع. ويتذكر مشروعك هذا الاختيار، وتضبطه الإعدادات للمشاريع الجديدة. وما دام لا شيء يُعزف على السلسلة الجانبية، يستمع ضبط النغمة إلى صوتك الغنائي، وتقول البطاقة ذلك.","docs.inputCheck.p1":"يُعِدّك Input Check، أعلى الرفّ، قبل أن تسجّل. اضغطه وغنِّ أو اعزف مقطعك لمدة عشر ثوانٍ؛ ويضيء مصباح التسجيل بالكهرماني بينما يستمع. ويحتاج إلى ثانيتين على الأقل من الصوت، ويطلب ذلك مرة أخرى إن سمع أقل مما يكفي.","docs.inputCheck.p2":"ثم يعرض ما سمعه — الذروة، والمستوى، والجهارة، وأرضية الضجيج، والهدير تحت 80 Hz، والصفير، والأصوات الانفجارية — وما يقترحه: مقبض الدخل، ليبلغ صوتك مستوى سليمًا، وعتبة البوابة، والتمرير العالي، وعتبة مزيل الصفير. ولا يضبط إلا الوحدات الموجودة في سلسلتك أصلًا؛ والوحدة التي تنقصها تقول «ليس في هذه السلسلة»، ولا يُضاف لك شيء.","docs.inputCheck.p3":"لا يتغير شيء حتى تضغط «تطبيق»، ويُلغي «تراجع» ما فعله «تطبيق» كله في خطوة واحدة. ويترك «تجاهل» كل شيء كما كان. وإن تعرّض المقطع للقص، يطلب منك أن تخفض كسب واجهة الصوت، لأنه لا يمكن التراجع عن القص بعد التسجيل.","docs.automation.p1":"تملك كل خانة 24 معلمة مضيف تحمل اسم الخانة (من F1 إلى B4)، وتأخذها مقابض الوحدة ومفاتيحها بالترتيب، فيستطيع DAW الخاص بك أتمتتها. ولا تتغير قائمة المعلمات أبدًا عندما تضيف وحدة أو تبدّلها أو تزيلها.","docs.automation.p2":"بعض الإعدادات لا تُؤتمت، لأن تغييرها في منتصف نغمة يُحدث نقرة: نوع نطاق EQ وميله، وميل المرشّح، وأوضاع مثل الكشف في مزيل الصفير. ومع ذلك تُحفظ مع مشروعك كغيرها.","docs.lamp.p1":"يضيء مصباح التسجيل أعلى الرفّ بالأخضر ما دامت في الرفّ وحدة وصوتك يدخل، ويومض بالأحمر عندما يتعرّض الإدخال للقص، ويبقى مطفأً في ما عدا ذلك. ويتحول إلى الكهرماني بينما يستمع Auto Key في وحدة ضبط النغمة بحثًا عن السلّم، وبينما يستمع Input Check.","docs.lamp.p2":"يعرض مقياسا الدخل والخرج على الجانبين القناتين اليسرى واليمنى، وبجانب مقياسَي الدخل يضبط مقبض الدخل مستوى الإشارة الداخلة، من −24 إلى +24 dB؛ ويستطيع DAW الخاص بك أتمتته. ولكل مقياس مصباح قص يبقى مضاءً حتى تنقر عليه. وتُظهر بطاقة الضاغط مقدار ما يخفضه من الصوت الغنائي، في أثناء ذلك.","docs.modules.p1":"في الإصدار 0.5.6 خمس وعشرون وحدة. كل واحدة منها من تصميم Takelight نفسه، ولا تدّعي أي منها أنها منتج آخر.","docs.modules.tune.title":"ضبط النغمة","docs.modules.tune.p1":"تصحيح الطبقة إلى سلّم — Auto Key أو «كروماتي» أو أحد السلالم الأربعة والعشرين — مع «سرعة التصحيح» من 0 إلى 400 ms، و«الطابع البشري» و«المرونة»، ومخطط للطبقة كما غُنّيت وبعد الضبط. وحدة واحدة في كل رفّ؛ انظر «ضبط النغمة وAuto Key» أعلاه.","docs.modules.trim.title":"ضبط الكسب","docs.modules.trim.p1":"الكسب والقطبية ومرشّح تمرير عالٍ مع اختيار الميل: أول ما يأتي في معظم السلاسل.","docs.modules.parametric.title":"EQ بارامتري","docs.modules.parametric.p1":"ثمانية نطاقات، كل منها جرسي أو رفّي أو قطع أو شقّ، مع قطع من 6 إلى 96 dB لكل أوكتاف. تعرض مقابضه نطاقًا واحدًا في كل مرة — اختر النطاق برقمه — ولكل نطاق نقطته على المنحنى.","docs.modules.console.title":"EQ طاولة المزج","docs.modules.console.p1":"EQ القناة في طاولة المزج: مرشّحا تمرير عالٍ وتمرير منخفض وأربعة نطاقات، بأربعة طوابع — بريطاني E وبريطاني G والفئة A وQ تناسبي.","docs.modules.program.title":"EQ البرنامج","docs.modules.program.p1":"تعزيز وخفض واسعان ولطيفان عند الطرفين المنخفض والعالي، ومرحلة الصمام لإضفاء الدفء.","docs.modules.opto.title":"ضاغط بصري","docs.modules.opto.p1":"تسوية سلسة للمستوى تتبع الأداء، من مقبض واحد هو «خفض الذروة»، بطابعين «بصري» و«بصري صمامي»، ضغطًا أو تحديدًا.","docs.modules.fet.title":"ضاغط FET","docs.modules.fet.p1":"سريع وبارز، بنسب ثابتة وإعداد «الكل» للضغط العنيف، وعنصر تحكم «المزج» للضغط المتوازي.","docs.modules.vca.title":"ضاغط VCA","docs.modules.vca.p1":"نظيف ودقيق، بطابعين «ناقل» و«قناة»، مع كشف RMS أو الذروة، وتمرير عالٍ للسلسلة الجانبية، وعنصر تحكم «المزج».","docs.modules.varimu.title":"ضاغط فاري-ميو","docs.modules.varimu.p1":"ضاغط صمامي ترتفع نسبته كلما اشتد عمله، فيبدأ بلطف ثم يمسك بثبات، مع ستة ثوابت زمنية؛ ويتحرر الثابتان 5 و6 ببطء أكبر كلما طالت مدة الضغط.","docs.modules.punch.title":"ضاغط الضربة","docs.modules.punch.p1":"ضاغط ذو طابع بخمسة طوابع، من «عادي» إلى «تشويه 3»، مع «سحق» للضغط الأقصى وعنصر تحكم «المزج».","docs.modules.vox.title":"مُسوّي مستوى الغناء","docs.modules.vox.p1":"يسوّي مستوى الصوت الغنائي بعنصرَي «العتبة» و«الخرج» فقط.","docs.modules.rider.title":"مُتابع المستوى","docs.modules.rider.p1":"يقود مستوى الصوت الغنائي نحو جهارة مستهدفة — يرفعه للكلمات الهادئة ويخفضه للكلمات العالية — ضمن مدى وبسرعة تحددهما أنت، ويترك الأنفاس بين الجمل كما هي. ويتيح له استباق اختياري مدته 10 ms أن يتحرك قبيل الكلمة مباشرة؛ ويضيف ذلك 10 ms من زمن التأخير، يُعلِم Takelight بها DAW الخاص بك.","docs.modules.deesser.title":"مزيل الصفير","docs.modules.deesser.p1":"يروّض أصوات «س» الحادة، بنطاق مقسوم أو نطاق عريض، بشكل جرسي أو رفّي، وبكشف نسبي أو مطلق.","docs.modules.gate.title":"بوابة","docs.modules.gate.p1":"بوابة أو موسِّع بين الجمل الغنائية، مع التثبيت والتخلّف ومرشّحات السلسلة الجانبية حتى لا تفتحه الأنفاس ولا التسرّب الصوتي.","docs.modules.saturation.title":"تشبّع","docs.modules.saturation.p1":"شريط وصمام ومحوّل ونفخ، مع فرط اعتيان كي تبقى التوافقيات التي يضيفها نقية.","docs.modules.exciter.title":"المُثير","docs.modules.exciter.p1":"يضيف توافقيات فوق تردد تختاره — فردية أو زوجية أو مزيجًا من الاثنين — لإضفاء الحضور والهواء. تُضاف التوافقيات وحدها؛ أما الصوت الغنائي نفسه فيمرّ دون أن يُمسّ.","docs.modules.lofi.title":"لو-فاي","docs.modules.lofi.p1":"بتات أقل ومعدل اعتيان أدنى، من 24 bits نزولًا إلى 4 ومن 48 kHz نزولًا إلى 1 kHz، مع التشويش المُضاف ومرشّح مانع للتداخل والدفع وعنصر تحكم «المزج».","docs.modules.limiter.title":"محدِّد","docs.modules.limiter.p1":"محدِّد للذروة الحقيقية: لا يرتفع الخرج أبدًا فوق السقف، حتى بين العينات.","docs.modules.delay.title":"التأخير","docs.modules.delay.p1":"خمسة طوابع — رقمي وشريط وتناظري وبينغ بونغ وصدى قصير. يُضبط زمنه بالميلي ثانية أو كقيمة نوتة من 1/64 إلى مازورتين، ومنها الثلاثيات والنوتات المنقوطة، على إيقاع مشروعك. مرشّحات في التغذية الراجعة، وخفض تحت الصوت الغنائي، والعرض؛ وفوق 100 % من التغذية الراجعة تتضخم التكرارات وتثبت بدل أن تنفلت.","docs.modules.reverb.title":"الصدى المتردد","docs.modules.reverb.p1":"خمسة طوابع — صفيحة وغرفة وقاعة وحجرة الصدى وأجواء — مع التأخير المسبق، وتلاشٍ من 0.1 إلى 20 ثانية، والحجم والتخميد والانتشار والتعديل ومرشّحات على الإرجاع. والتلاشي هو الزمن الذي يستغرقه الذيل لينخفض بمقدار 60 dB.","docs.modules.reversegate.title":"البوابة المعكوسة","docs.modules.reversegate.p1":"الصدى المتردد المعكوس: بعد كل صوت، موجة صدى تتضخم على مدى مدة البوابة، من 50 ms إلى ثانية، ثم تتوقف فجأة. لا تستبق أبدًا، لذا لا تضيف أي زمن تأخير وتعمل بينما تسجّل.","docs.modules.doubler.title":"المضاعِف","docs.modules.doubler.p1":"يحوّل تسجيلًا واحدًا إلى صوتين أو ثلاثة أو أربعة أصوات، كل منها متأخر قليلًا، ينجرف قليلًا في التوقيت وطبقة الصوت، وموزّع على المجال الستيريو، بطابعين «مُحكَم» و«واسع». وعند جمعه إلى مونو يبقى قريبًا من مستوى الصوت الغنائي نفسه.","docs.modules.chorus.title":"الكورس","docs.modules.chorus.p1":"كورس بصوتين، يرتفع أحدهما في طبقته بينما ينخفض الآخر، مع المعدّل والعمق والمزج والدفع؛ وعند مزج بنسبة 50 % يحافظ على المستوى ويُجمَع إلى مونو بنقاء.","docs.modules.width.title":"العرض","docs.modules.width.p1":"يضيّق الصورة الستيريو أو يوسّعها، من مونو عند 0 % إلى 200 %، دون تغيير مجموع المونو، مع تأخير Haas يصل إلى 30 ms على الجانب الأيمن لتوسيع صوت غنائي مونو.","docs.modules.shifter.title":"مُزيح الطبقة","docs.modules.shifter.p1":"يرفع الصوت أو يخفضه حتى أوكتافين، وتُزاح فورمانتاته وحدها حتى أوكتاف، مع مقبض «المزج»: الأدليب أخفض بأوكتاف. ومثل ضبط النغمة، ينتظر 21 ميلي ثانية، أو 4 في وضع Tracking.","docs.project.p1":"يحتفظ مشروعك بالسلسلة، وبكل وحدة وكل مقبض، وبالعرض، وبمقابض الوضع البسيط الأربعة، وبجانبي المقارنة، وبما يستمع إليه ضبط النغمة. وإن تعذّرت قراءة إعدادات مشروع، يُفتح على السلسلة الافتراضية ويقول ذلك مرة واحدة، فوق مساحة العمل، حتى تُغلق الرسالة.","docs.agreement.p1":"عند فتحه لأول مرة، يعرض Takelight اتفاقية الترخيص وإخلاء المسؤولية. وحتى توافق، لا يفعل شيئًا سوى تمرير صوتك دون تغيير، لذلك لا يُسكت الرفض أي مسار أبدًا.","docs.agreement.p2":"تُحفظ إجابتك على جهازك وتشترك فيها كل نسخة مفتوحة من Takelight، في كل DAW وفي التطبيق المستقل. يمكنك قراءة الاتفاقية مجددًا وقبولها في أي وقت.","docs.settings.p1":"في الإعدادات تختار الوضع الفاتح أو الداكن واللغة، من بين أمور أخرى. اختياراتك تخص الجهاز لا المشروع: وتسري على كل نسخة من Takelight عليه.","docs.language.p1":"يتحدث Takelight وهذا الموقع ثماني عشرة لغة، والعربية من اليمين إلى اليسار. ولا تُترجم أسماء الفنانين أبدًا.","docs.disclaimer.p1":"تدل أسماء الفنانين على أسلوب، ولا شيء أكثر. لا يرتبط Freally Takelight بأي فنان أو منتج أو مهندس أو شركة تسجيلات أو مطبوعة أو صانع إضافات، ولا يحظى بتأييدهم أو رعايتهم أو موافقتهم. جميع الأسماء والعلامات التجارية ملك لأصحابها، ولا تُستخدم صورة أي فنان أو شعاره أو توقيعه أو أعماله الفنية في أي مكان.","docs.disclaimer.p2":"تطبّق السلسلة معالجة؛ لا تغيّر من يغني، ولا تعد أي سلسلة بصوت بعينه. وحدات Takelight من تصميمه هو، ولا تدّعي أنها أي منتج آخر.","docs.disclaimer.p3":"هذا ملخص. يعرض Takelight نص إخلاء المسؤولية كاملًا مع اتفاقية الترخيص.","docs.privacy.p1":"لا تتصل الإضافة ولا التطبيق المستقل بالإنترنت أبدًا: لا حساب ولا قياس عن بُعد ولا شيفرة شبكات، وتمنعها بوابة البناء. صوتك لا يغادر جهازك أبدًا، وملف المرجع الذي تحمّله للمقارنة A/B يبقى في الذاكرة فقط.","docs.privacy.p2":"بدءًا من الإصدار 1.0، يتحقق برنامج مساعد منفصل من التحديثات ويفعّل ترخيصك — فقط عندما تطلب ذلك. ولا ينزّل أي شيء ولا يثبّته أبدًا.","docs.report.p1":"راسلنا على freallyproducts@gmail.com. عندما يتعطّل Takelight نفسه، تعرض الرسالة التي يُظهرها «أبلِغ»: يفتح في متصفحك صفحة تعرض كل ما سيُرسل، ولا يغادر جهازك شيء حتى تضغط «إرسال». وبعد الانهيار، يعرض التشغيل التالي الأمر نفسه.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.badge.progress":"v0.5.6 منجز · v0.6.0 هو التالي","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.ladder.later":"لاحقًا","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">عشرة تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Takelight، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.status.devVersion":"قيد التطوير · v0.5.6","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.numbers.lead":"كل رقم محسوب من التطبيق نفسه. لا شيء مُقدَّر، ولا شيء مُقرَّب إلى الأعلى.","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.later":"بعد ذلك، ولم يُجدوَل بعد","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Takelight، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","kit.zoom.close":"إغلاق","changelog.1231a0c0224a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.6</span><time class=\"release__date\" datetime=\"2026-10-27\">2026-10-27</time></span><span class=\"release__title\">بطاقات مرئية</span>","changelog.ca7f81d415d0":"تعرض بطاقة كل وحدة الآن ما تفعله، لا مقابضها وحدها: ترسم وحدات EQ منحناها فوق صوتك الغنائي في أثناء تشغيله، وتُظهر الضواغط أين يقع صوتك الغنائي وكم تقتطع، وترسم البقية تكراراتها وتلاشيها ومجالها الستيريو ومنحناها. وكل صورة محسوبة بالرياضيات نفسها التي تصنع الصوت.","changelog.6b02e0d363a4":"أُضيف","changelog.c885adad0ca5":"<strong>بطاقات EQ</strong> — ترسم وحدات EQ بارامتري وEQ طاولة المزج وEQ البرنامج منحناها فوق طيف حيّ لصوتك الغنائي، قبل EQ (باهتًا) وبعده (ساطعًا)، مع إبقاء القمم لحظةً. لكل نطاق نقطة على المنحنى: اسحبها لتحريك تردده وكسبه معًا، وأدر عجلة الفأرة فوقها لعرض النطاق، وانقر عليها نقرًا مزدوجًا لإعادته إلى وضعه، أو استخدم مفاتيح الأسهم. وتتنقل نقاط EQ البرنامج بين تردداته كما تفعل مقابضه، وتستقر نقاط EQ طاولة المزج في طابع الفئة A على الدرجات التي يتخذها. ويرسم مزيل الصفير النطاق الذي يستمع إليه والخفض الذي يُحدثه، ويرسم ضبط الكسب مرشّح التمرير العالي الخاص به.","changelog.e4155cb8a38e":"<strong>بطاقات الضواغط</strong> — يرسم الضاغط البصري وضاغط FET وضاغط VCA وضاغط فاري-ميو وضاغط الضربة ومُسوّي مستوى الغناء ومُتابع المستوى والمحدِّد منحناها، مستوى الدخل مقابل مستوى الخرج، مع نقطة حيث يقع صوتك الغنائي عليه الآن، وتحته خفض الكسب في آخر أربع ثوانٍ. اسحب العتبة على طول المنحنى، أو استخدم مفاتيح الأسهم؛ فهي تدير المقبض الذي يضبطها.","changelog.ec53ddb6a430":"<strong>بطاقة البوابة</strong> — منحناها، وتحته المستوى الذي تسمعه مقابل عتبتها خلال آخر أربع ثوانٍ، مظلَّلًا حيث تكون مغلقة.","changelog.7c482c32b414":"<strong>بطاقات المساحة</strong> — تكرارات التأخير على خط زمني مقابل نبض مشروعك ومازورته، كلٌّ منها بالشدة التي تتركها له التغذية الراجعة والمرشّحات (في بينغ بونغ تقع اليسرى فوق الخط واليمنى تحته)؛ وتلاشي الصدى المتردد — التأخير المسبق والانعكاسات المبكرة والذيل؛ وتصاعد البوابة المعكوسة؛ والمجال الستيريو للمضاعِف والكورس والعرض، كما يُرى من الأعلى.","changelog.580a2bd46885":"<strong>بطاقات اللون</strong> — يرسم التشبّع والمُثير ولو-فاي منحناها، وإلى جانبه التوافقيات التي يضيفها إلى صوتك الغنائي كما هو الآن.","changelog.2a6141e43be0":"عُدِّل","changelog.4aa1a07ba478":"<strong>السحب فوق مقبضين خطوة واحدة في التراجع</strong> — تحريك نقطة نطاق في EQ يغيّر تردده وكسبه معًا، وتراجع واحد يستعيد السحب كله، مهما طال إبقاؤك له ساكنًا.","changelog.c64f3e0add84":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.5</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">Input Check والإضافات والإعدادات المسبقة</span>","changelog.f6741058398a":"اضبط مستواك قبل أن تسجّل، واحتفظ بنسخك الخاصة من أي سلسلة، وتراجع عن أي تغيير بمفتاح واحد. ويستطيع Auto Key في ضبط النغمة الآن أن يجد السلّم من الإيقاع.","changelog.145f9c7721e2":"<strong>Input Check</strong> — اضغط Input Check في الرفّ وغنِّ أو اعزف مقطعك لمدة عشر ثوانٍ؛ ويضيء مصباح التسجيل بالكهرماني بينما يستمع. ثم يعرض ما سمعه (الذروة والمستوى والجهارة وأرضية الضجيج والهدير والصفير والأصوات الانفجارية) وما يقترحه: مقبض الدخل، والبوابة والتمرير العالي ومزيل الصفير الموجودة في السلسلة أصلًا. لا يتغير شيء حتى تضغط «تطبيق»، والوحدة غير الموجودة في السلسلة تقول ذلك — ولا يُضاف لك شيء. وإن تعرّض المقطع للقص، يطلب منك أن تخفض كسب واجهة الصوت.","changelog.807271b61fd0":"<strong>إعداداتك المسبقة</strong> — يحفظ «حفظ إعداد مسبق…» السلسلةَ كما شكّلتها، باسم تختاره، في ملف داخل المستندات › Freally Takelight › Presets. ويحمّلها «إعداداتي المسبقة…» ويعيد تسميتها ويصدّرها ويحذفها، ويستورد إعدادًا مسبقًا أرسله إليك أحد (ويُرفض الملف الذي ليس إعدادًا مسبقًا، مع ذكر السبب). وتظهر إعداداتك المسبقة في البحث أيضًا، تحت «إعداداتي المسبقة»، مع السلسلة التي صُنع منها كل منها. وحين تُحدَّث تلك السلسلة، يتبعها إعدادك المسبق ويحتفظ بتعديلاتك.","changelog.2110305b2ce9":"<strong>التراجع والإعادة</strong> — كل تغيير في الصوت، حتى 100 خطوة: مقبض (خطوة لكل سحب)، ووحدة تُضاف أو تُزال، وطابعها، و«تجاوز» و«منفرد»، والإرسالات والمنزلقات، والمقابض الكبيرة الأربعة، ومقبض الدخل، وسلسلة أو إعداد مسبق يُحمَّل، و«تطبيق» في Input Check. بالسهمين في الشريط العلوي، أو بـ Ctrl+Z وCtrl+Shift+Z (وCtrl+Y أيضًا؛ ⌘Z و⌘⇧Z على Mac) ما دامت النافذة في موضع التركيز. لا يُتراجع أبدًا عن العرض والسمة واللغة ومرجع A/B، ولا عن أتمتة DAW الخاص بك؛ والتبديل بين A وB يبدأ سجلّ ذلك الجانب من جديد.","changelog.065bc3159eeb":"<strong>مقبض الدخل</strong> — بجانب مقياسَي الدخل، مستوى الإشارة الداخلة، من −24 إلى +24 dB. يضبطه Input Check، ويستطيع DAW الخاص بك أتمتته.","changelog.0c42df2ca995":"<strong>Auto Key من الإيقاع</strong> — يستطيع ضبط النغمة أن يستمع إلى مدخل سلسلة جانبية: أرسل إيقاعك إلى السلسلة الجانبية في Freally Takelight واختر <em>يستمع إلى: السلسلة الجانبية</em> في بطاقة ضبط النغمة، فيتبع Auto Key تآلفات الإيقاع بدلًا من صوتك. ويتذكر كل مشروع اختياره؛ وتضبطه الإعدادات للمشاريع الجديدة. وحين لا يُعزف شيء على السلسلة الجانبية، يستمع ضبط النغمة إلى صوتك الغنائي ويقول ذلك.","changelog.057d5c78c13a":"<strong>مربّعا حوار «فتح» و«حفظ» ينتميان إلى النافذة</strong> — يُفتحان أمام Freally Takelight ويُبقيانه خلفهما حتى تختار.","changelog.adf9645e2b40":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">الضوء الأول — Drake والمتصفح</span>","changelog.9befafdec87e":"أول إصدار مكتمل: ابحث عن فنان، واختر عصرًا، واضغط تشغيل، فتُحمَّل السلسلة الصوتية كلها بنقرة واحدة. وصلت عصور Drake وثماني عشرة سلسلة للأنواع الموسيقية، مع أربعة مقابض كبيرة لتشكيلها، ومرجع للمقارنة به، ونسخة ثانية من سلسلتك للمقارنة معها.","changelog.abd39e3e1804":"<strong>متصفح السلاسل</strong> — اكتب اسم فنان أو نوعًا موسيقيًا في البحث (Ctrl+K، أو Cmd+K على Mac)، فتُرتَّب السلاسل حسب العصر والدور وأنت تكتب، والألقاب مشمولة. وحين يكون الحقل فارغًا يعرض السلاسل التي حمّلتها آخر مرة؛ ولفنان ليس في المكتبة بعد يقترح سلسلة نوع موسيقي. وكل خطوة تعمل من لوحة المفاتيح.","changelog.6372ffc30569":"<strong>Drake</strong> — ثلاثة عصور: عصر So Far Gone (2009)، وعصر Take Care (2011)، والعصر الحديث (2016–2026)، مع سلسلة رئيسية لكل منها وسلسلة إضافات للعصر الحديث، وسلسلة مؤثرات من عصر Take Care تعيش على قنوات الإرجاع وحدها.","changelog.8def9e786270":"<strong>ثماني عشرة سلسلة للأنواع الموسيقية</strong> — سلسلة رئيسية وسلسلة إضافات لكل من التراب (عقد 2000 وعقد 2010)، ودريل شيكاغو، والإيمو راب، والـ R&amp;B الكلاسيكي، والبوب الحديث، والروك، والكانتري بوب، والريغيتون.","changelog.3370f1b4141c":"<strong>الوضع البسيط</strong> — مصباح التسجيل، واسم السلسلة، وأربعة مقابض كبيرة، ومقياسا الدخل/الخرج؛ ويعرض الوضع المتقدم الرفّ كله. ويتذكر كل مشروع الوضع الذي تُرك فيه، وتختار في الإعدادات الوضع الذي يُفتح فيه مشروع جديد.","changelog.b4ff7f2e9dce":"<strong>أربعة مقابض</strong> — «ضبط النغمة» (سرعة ضبط الصوت الغنائي ومدى طبيعيته)، و«النبرة» (أكثر قتامة أو أكثر سطوعًا، ومزيل الصفير يتبعها)، و«المساحة» (كل إرسالات المؤثرات معًا)، و«المقدار» (السلسلة كلها مقابل صوتك الجاف). وحين يكون «ضبط النغمة» و«النبرة» و«المساحة» في المنتصف و«المقدار» في أقصاه، تعمل السلسلة كما صُمّمت، وهكذا تُحمَّل كل سلسلة. ويستطيع DAW الخاص بك أتمتة المقابض الأربعة كلها.","changelog.8988c7fcad46":"<strong>مرجع A/B</strong> — افتح أغنية أو صوتًا غنائيًا مكتملًا (WAV أو AIFF أو FLAC أو MP3، حتى 20 دقيقة)، أو أفلته على النافذة، فيشغّله B من حيث يقف DAW الخاص بك (من البداية في التطبيق المستقل)، بانتقال سلس خلال 20 ms ومطابَقًا لجهارة صوتك الغنائي، فتحكم على النبرة لا على المستوى. ويبقى في الذاكرة فقط: لا يُحفظ أبدًا مع المشروع ولا في إعداد مسبق ولا في أي مكان آخر، ويُرفض أي ملف على محرك أقراص شبكي.","changelog.41af758b9239":"<strong>مقارنة السلاسل</strong> — نسختان من سلسلتك، A وB: تبدأ B نسخةً من A، وتحتفظ كل منهما بتعديلاتها، وتبدّل نقرة واحدة بينهما.","changelog.595ee8591a1b":"<strong>المشاريع تتذكر</strong> — تُحفظ السلسلة والعرض ومقابض الوضع البسيط وجانبا المقارنة مع مشروعك. والمشروع الذي تتعذّر قراءته يُفتح على السلسلة الافتراضية ويقول ذلك مرة واحدة.","changelog.4794b815283f":"<strong>مؤشر Freally</strong> — حلقة في قلبها نقطة، تكبر فوق كل ما يمكنك الضغط عليه.","changelog.3ad2505d4a1e":"<strong>مفاتيح التبديل</strong> — كل مفتاح تبديل رمادي حين يكون مطفأً، وأبيض تحت المؤشر، وأخضر Freally حين يكون مُشغَّلًا، تحت المؤشر أو لا.","changelog.d526eacf003a":"<strong>الرفّ الممتلئ يقول ذلك</strong> — يتّسع الرفّ لعدد من المقابض يساوي ما يستطيع Freally Takelight تحريكه دفعة واحدة؛ والوحدة التي تتجاوز ذلك تُرفض برسالة تقول إن الرفّ ممتلئ.","changelog.81c6aadde005":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">ضبط النغمة</span>","changelog.ee8aa777588f":"وصل تصحيح الطبقة: تشدّ وحدة ضبط النغمة صوتك الغنائي إلى نغمات سلّمه مع الحفاظ على فورمانتاته، وتجد السلّم بنفسها، وتنخفض إلى بضع ميلي ثوانٍ من زمن الانتقال أثناء التسجيل؛ ويرفع مُزيح الطبقة الصوت أو يخفضه حتى أوكتافين.","changelog.e84a04d8e61c":"<strong>ضبط النغمة</strong> — تصحيح الطبقة بمعالجة الإشارة الكلاسيكية: «سرعة التصحيح» من 0 ms (الصوت الحاد المتدرّج) إلى 400 ms، و«الطابع البشري» ليدع النغمات الطويلة تتنفس، و«المرونة» للحفاظ على الانزلاقات والاهتزاز. يحتفظ صوتك بطابعه، لأن فورمانتاته تبقى في مكانها.","changelog.1b908b3463cd":"<strong>Auto Key</strong> — تستمع وحدة ضبط النغمة إلى صوتك الغنائي وتستقر على سلّمه خلال نحو أربع ثوانٍ من الغناء، وتبقى كروماتية حتى ذلك الحين. ثبّت السلّم الذي تسمعه بنقرة واحدة، أو اختر أيًّا من السلالم الأربعة والعشرين، أو «كروماتي».","changelog.539fbc62230d":"<strong>مخطط الطبقة</strong> — آخر أربع ثوانٍ من صوتك، الطبقة المغنّاة والطبقة بعد الضبط، تحت النغمة التي تُشدّ إليها.","changelog.0f378cb53cb4":"<strong>Tracking</strong> — أثناء تسجيل الـ DAW (أو حين تشغّله)، تعمل وحدة ضبط النغمة بزمن انتقال من بضع ميلي ثوانٍ لتغنّي عبر السلسلة؛ وعند المزج تُبلغ عن زمن انتقالها الكامل فيُبقي الـ DAW الصوت الغنائي متزامنًا مع الإيقاع.","changelog.2e82019ea87e":"<strong>مُزيح الطبقة</strong> — يرفع الصوت أو يخفضه حتى أوكتافين، وتُزاح فورمانتاته وحدها حتى أوكتاف، ممزوجًا بالصوت كما كان: الأدليب أخفض بأوكتاف.","changelog.ba9e41780afd":"<strong>مصباح التسجيل يستمع</strong> — يضيء بالكهرماني ما دام Auto Key لا يزال يستمع بحثًا عن السلّم.","changelog.e86e8d397ace":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">المساحة</span>","changelog.c223312c046d":"وصلت قنوات إرجاع المؤثرات الأربع، مع تأخيرات وصدى متردد ومضاعفة وعرض على إيقاع مشروعك، ومفتاح «رمي» في كل قناة إرجاع، وأربع وحدات أخرى للإدراجات.","changelog.eaa251798d7e":"<strong>أربع قنوات لإرجاع المؤثرات</strong> — من A إلى D، تُغذّى كل منها من نهاية الإدراجات عبر مقبض «الإرسال» الخاص بها، ولها ثلاث خانات ومنزلق مستوى خاص بها، وتنضم إلى الصوت الجاف في طريقه إلى الناقل الصوتي.","changelog.ebb30e23847f":"<strong>الرمي</strong> — اضغط مع الاستمرار على مفتاح «رمي» في قناة إرجاع فيُرمى الصوت الغنائي إليها، وإرسالها عند 0 dB حتى تُفلت المفتاح. و«رمي» من A إلى D معلمات مضيف أيضًا، فيستطيع DAW الخاص بك تسجيل الرمية وإعادة تشغيلها.","changelog.39cab35a5560":"<strong>التأخير</strong> — رقمي وشريط وتناظري وبينغ بونغ وصدى قصير، يُضبط بالميلي ثانية أو كقيمة نوتة على إيقاع مشروعك، مع مرشّحات في التغذية الراجعة، وخفض تحت الصوت الغنائي، والعرض.","changelog.d45fe717d01c":"<strong>الصدى المتردد</strong> — صفيحة وغرفة وقاعة وحجرة الصدى وأجواء، مع تلاشٍ من 0.1 إلى 20 ثانية؛ و<strong>البوابة المعكوسة</strong>، صدى متردد معكوس يتضخم دون أن يضيف أي زمن تأخير.","changelog.4db2c68f321a":"<strong>المضاعِف والكورس والعرض</strong> — من صوتين إلى أربعة أصوات من تسجيل واحد، وكورس بصوتين، وعرض ستيريو من مونو إلى 200 % مع تأخير Haas.","changelog.8be315d62f9e":"<strong>أربع وحدات أخرى للإدراجات</strong> — ضاغط فاري-ميو بستة ثوابت زمنية، ومُتابع المستوى، والمُثير، ولو-فاي.","changelog.2d718978085b":"<strong>على إيقاع مشروعك</strong> — التأخير المضبوط على قيمة نوتة يتبع سرعة إيقاع DAW الخاص بك، حتى حين تتغير في أثناء الأغنية.","changelog.e3c80cfe9d31":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span><span class=\"release__title\">Joint وأولى الوحدات وموقع التوثيق</span>","changelog.521a85ebded1":"وصل الرفّ: Joint واحد لسلسلة صوتية كاملة، وثلاث عشرة وحدة من تصميم Takelight نفسه على أجهزة مُصيَّرة، ومصباح التسجيل.","changelog.657c896de46f":"<strong>Joint</strong> — رفّ واحد بترتيب الإشارة: مرحلة أولى من خانتين، واثنا عشر إدراجًا، وناقل صوتي من أربع خانات، ويُعلَم DAW الخاص بك بزمن تأخيره، ويمزج «المقدار» السلسلة كلها مع الصوت الجاف.","changelog.44955680f91b":"<strong>تغييرات دون نقرات</strong> — أضف الوحدات وأزلها وبدّلها والمقطع يعمل: يُجهَّز الرفّ الجديد بعيدًا عن الصوت ويدخل بانتقال مدته 30 ميلي ثانية، ويدخل الطابع الجديد بانتقال سلس، وينزلق كل مقبض بنعومة.","changelog.5883cafdd389":"<strong>ثلاث عشرة وحدة</strong> — ضبط الكسب؛ وEQ البارامتري وEQ طاولة المزج وEQ البرنامج؛ والضاغط البصري وضاغط FET وضاغط VCA وضاغط الضربة؛ ومُسوّي مستوى الغناء؛ ومزيل الصفير؛ والبوابة؛ والتشبّع؛ ومحدِّد للذروة الحقيقية.","changelog.da4d68a37948":"<strong>شاشة الرفّ</strong> — كل وحدة بطاقة من أجهزة مُصيَّرة، بطابعها و«تجاوز» و«منفرد» وخفض الكسب، وكل عنصر تحكم في متناول لوحة المفاتيح، بـ 18 لغة.","changelog.19b404056636":"<strong>الأتمتة</strong> — تحرّك معلمات المضيف الـ 24 لكل خانة عناصر تحكم وحدتها بالترتيب، فلا تتغير قائمة المعلمات أبدًا.","changelog.93ce19272231":"<strong>مصباح التسجيل والمقاييس</strong> — مصباح الكابينة، المُصيَّر في Blender بالوضعين الداكن والفاتح، يضيء بالأخضر ما دامت في الرفّ وحدة وصوتك يدخل، ويومض بالأحمر عند القص؛ ومقياسا الدخل والخرج بمصباحَي قص.","changelog.54bf2d68a5db":"<strong>أبلِغ عن هذا</strong> — عندما يتعطّل Takelight نفسه، أو بعد الانهيار، تعرض صفحة في متصفحك كل ما سيرسله البلاغ، ولا يُرسل شيء حتى تضغط «إرسال».","changelog.42b61e5ef13f":"<strong>موقع التوثيق، مكتملًا</strong> — الصفحة الرئيسية والميزات والدليل وسجل التغييرات وسلّم الإصدارات، بـ 18 لغة.","changelog.2178abb38e7d":"<strong>اتفاقية الترخيص الآن في إصدارها 2</strong>، لذا يطلب منك Takelight قبولها مرة أخرى. وصارت هي وإخلاء المسؤولية أقصر وأوضح.","changelog.e6a2eb660b78":"<strong>إعداد أقل</strong> — اختفت النقاط الملوّنة بجانب القيم، واختفى معها إعدادها. ولا تسرد قائمة الشكر إلا إشعارات الترخيص.","changelog.5758b5c96327":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.1</span><time class=\"release__date\" datetime=\"2026-10-13\">2026-10-13</time></span><span class=\"release__title\">الإعدادات بتصميم جديد</span>","changelog.898338328178":"<strong>الإعدادات بتصميم جديد</strong> — تُفتح من ترس في الشريط العلوي وتُغلق بعلامة ×؛ السمة مفتاح داكن/فاتح بقمر وشمس، وكل خيار قصير عنصر مقسّم بمؤشر منزلق، ونصوص «حول» الطويلة قائمة من الصفوف.","changelog.5c7b3a54f6e0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span><span class=\"release__title\">الأساس، والعمود الفقري للتكامل المستمر، وطريق الإصدار</span>","changelog.e7f1a5798692":"Freally Takelight فارغ يُحمَّل في المضيف، ويمرّر الصوت، ويضع في مكانها كل بوابة وكلا فرعي التكامل المستمر وطريق الإصدار قبل أن توجد ميزة واحدة.","changelog.82a7fc560af2":"<strong>الإضافة، فارغة، بكل الصيغ</strong> — CLAP من nih-plug، وVST3 وAU يُسقطهما clap-wrapper من الملف الثنائي نفسه، وتطبيق مستقل. مداخل أحادية وستيريو، ومخرج ستيريو؛ ويمرّ الصوت دون تغيير.","changelog.9dc28fd94514":"<strong>مجموعة المعلمات</strong> — الإدخال والإخراج والمقدار والتجاوز والتتبع وثلاثة ماكرو وأربع رميات و30 خانة في كل منها 24 معلمة عامة، كي لا يغيّر تحميل سلسلة قائمة معلمات المضيف أبدًا.","changelog.7a8b66c5fe5a":"<strong>هيكل المحرر</strong> — طقم واجهة Freally بالداكن والفاتح، واتفاقية الترخيص وإخلاء المسؤولية عند التشغيل الأول، والإعدادات وحول، و18 لغة مع تخطيط من اليمين إلى اليسار.","changelog.ec039c3098d0":"<strong>البوابات</strong> — لا ذكاء اصطناعي، ولا شبكة، ولا شيفرة مستعارة، وأسماء المنتج والكلمات المحظورة، ولا تنزيلات قبل 1.0، وسلّم الإصدارات، والتراخيص، والحزم المشتركة، وطقم الواجهة وفن الأجهزة، واللغات وCSS المنطقي، وانحراف الروابط، ولا حجز للذاكرة على خيط الصوت.","changelog.872b0df7744d":"<strong>تكامل مستمر مستضاف ذاتيًا</strong> — <code>npm run ci:local</code> (Windows) و<code>npm run ci:linux</code> (Docker Desktop)، قائمة بوابات واحدة؛ وPlaywright على المحرر وعلى التطبيق المستقل الحقيقي.","changelog.5cbd8ff53c0a":"<strong>طريق الإصدار</strong> — يبني <code>npm run release:local</code> الوسم نفسه تمامًا، ويتحقق من الحزم، ويكتب مجلد الإصدار مع المجاميع الاختبارية، ويقلّص <code>target/</code> إليه، ويثبّت VST3 وCLAP عبر مطالبة UAC واحدة.","changelog.4e9699d53d2d":"<strong>هيكل موقع التوثيق</strong> وهيكل بيانات السلاسل (<code>tlc validate</code> و<code>tlc import-roster</code>)."};
